def split_protected(line):
    """returns list of (text, is_protected)"""
    out=[]; i=0; n=len(line)
    while True:
        k=line.find('\x1b[', i)
        if k<0:
            if i<n: out.append((line[i:],False))
            break
        if k>i: out.append((line[i:k],False))
        j=line.find('\x1b[0m', k)
        if j<0:
            out.append((line[k:],True)); break
        out.append((line[k:j+4],True)); i=j+4
    return out

def hl2(line, enable=('uuids','pointers','numbers')):
    res=[]
    for txt,prot in split_protected(line):
        res.append(txt if prot else hl(txt,enable))
    return ''.join(res)
